// Helper to recursively find the structured object from the parser output
function findFields(obj) {
  if (!obj || typeof obj !== 'object') return null;
  if (obj.case_study !== undefined) return obj;
  for (const key of Object.keys(obj)) {
    const found = findFields(obj[key]);
    if (found) return found;
  }
  return null;
}

// Extract parsed response from current item
const currentInput = $input.item.json || {};
const raw = findFields(currentInput) || {};

// Fetch source details from the matching input item
const originalItem = $("Code in JavaScript").item.json || {};
const sourceNotes = originalItem.notes || '';
const projectName = originalItem.project_name || 'unknown_project';

const caseStudy = raw.case_study || '';
const webCard = raw.web_card || '';
const linkedin = raw.linkedin || '';

// Handle failed extraction
if (!caseStudy && !webCard && !linkedin) {
  return {
    json: {
      project_name: projectName,
      validation_status: 'ERROR_NO_DATA_FOUND',
      debug_raw_input: JSON.stringify(currentInput).slice(0, 1000)
    }
  };
}

// Perform validation check on numbers
const combinedOutput = `${caseStudy} ${webCard} ${linkedin}`;
const numberPattern = /\d+(\.\d+)?%?/g;

const outputNumbers = combinedOutput.match(numberPattern) || [];
const sourceNumbers = sourceNotes.match(numberPattern) || [];
const fabricated = outputNumbers.filter(n => !sourceNumbers.includes(n));

// Return a single JSON object for THIS item
return {
  json: {
    project_name: projectName,
    case_study: caseStudy,
    web_card: webCard,
    linkedin: linkedin,
    validation_status: fabricated.length === 0 ? 'PASS' : 'FLAGGED',
    fabricated_numbers: fabricated,
    checked_at: new Date().toISOString()
  }
};
